let agentJob=null,agentPolling=null,agentProviders=[],agentPanelMode='agent',activeFinding=-1;
function jobStale(finding){if(!data||!agentJob)return true;const source=agentJob.files.find(f=>f.path===finding.path),now=data.files.find(f=>f.path===finding.path);return !source||!now||source.fingerprint!==now.fingerprint}
function renderAgentReview(){const result=$('#agentResult');if(!result)return;const running=agentJob?.status==='running';$('#runFile').disabled=running||!file();$('#runAll').disabled=running||!data?.files.length;$('#agentProvider').disabled=running;$('#cancelAgent').classList.toggle('hidden',!running);if(agentJob&&!data){result.innerHTML='<div class="muted">正在读取仓库并核对审查版本…</div>';return}if(!agentJob){result.innerHTML='<div class="agentempty"><span class="reviewglyph">✧</span><h2>让 Agent 先帮你找重点。</h2><p>审查真实变更，给出可定位的问题和核对建议。你来决定哪些值得处理。</p><div class="agenthint">当前是课程笔记：检查逻辑一致性、概念遗漏与引用依据。没有课程原文的判断会标记为“待核实”。</div></div>';return}const names={codex:'Codex',claude:'Claude Code'},job=agentJob,elapsed=Math.round((Date.now()-new Date(job.startedAt).getTime())/1000);const title=`<div class="agentreceipt"><span>${names[job.provider]} · ${job.files.length} 个文件</span><span>${new Date(job.startedAt).toLocaleTimeString()}</span></div>`;if(running){result.innerHTML=title+`<div class="running"><span class="pulse"></span> ${esc(job.phase)}<p class="muted">已运行 ${elapsed} 秒 · 可继续在左侧阅读</p><p class="muted">审查冻结快照，结果不会自动标记为通过。</p></div>`;return}if(job.status==='error'||job.status==='cancelled'){result.innerHTML=title+`<div class="agenterror"><b>${job.status==='cancelled'?'审查已停止':'审查未完成'}</b><p>${esc(job.error||'可重新选择范围后发起审查。')}</p><p class="muted">这不代表“未发现问题”。</p></div>`;return}const report=job.report;if(!report){result.innerHTML=title;return}const stale=job.files.filter(f=>!data?.files.some(n=>n.path===f.path&&n.fingerprint===f.fingerprint));result.innerHTML=title+(stale.length?`<div class="stalebanner">↻ ${stale.length} 个文件已变化，相关意见基于旧版本，请重新审查。</div>`:'')+`<div class="agentsummary">${esc(report.summary)}</div><div class="findingsummary"><span>${report.findings.filter(f=>f.kind==='issue').length} 个问题</span><span>${report.findings.filter(f=>f.kind==='verify').length} 个待核实</span><span class="muted">需人工确认</span></div>`+report.findings.map((f,i)=>`<article class="finding ${activeFinding===i?'findingactive':''} ${jobStale(f)?'stalefinding':''}"><div class="findingtop"><span class="priority ${f.severity==='P1'?'p1':''}">${esc(f.severity)}</span><span class="findingkind">${f.kind==='verify'?'待核实':'问题'}</span>${jobStale(f)?'<span class="amber">旧版本</span>':''}</div><button class="findingtitle" data-finding="${i}">${esc(f.title)}</button><button class="findinglocation mono" data-finding="${i}">${esc(f.path.split('/').pop())}:${f.start_line}–${f.end_line} ↗</button><p>${esc(f.body)}</p><details><summary>依据与处理建议</summary><blockquote>${esc(f.evidence)}</blockquote><p>${esc(f.suggestion)}</p></details><button class="outline usefinding" data-adopt="${i}" ${jobStale(f)?'disabled':''}>＋ 采用为审查反馈</button></article>`).join('')+(report.findings.length===0?'<div class="agenthint">此范围未发现具体问题。请继续人工确认；Agent 结果不会替代你的审查。</div>':'')+(job.skipped.length?`<div class="agenthint">未审查：${job.skipped.map(esc).join('、')}</div>`:'')+`<details class="coverage"><summary>审查范围与限制</summary><p>${report.coverage.map(esc).join('<br>')}</p>${report.limitations.map(x=>`<p class="muted">${esc(x)}</p>`).join('')}</details>`;result.querySelectorAll('[data-finding]').forEach(b=>b.onclick=()=>locateFinding(+b.dataset.finding));result.querySelectorAll('[data-adopt]').forEach(b=>b.onclick=()=>adoptFinding(+b.dataset.adopt))}
function locateFinding(index){const f=agentJob?.report?.findings[index];if(!f)return;if(jobStale(f))return toast('文件已变化，这条意见属于旧版本，请重新审查');activeFinding=index;current=f.path;layout='split';baseline='head';view('review');renderFile();renderList();renderAgentReview();let target=[...document.querySelectorAll('.diffrow')].find(row=>+row.children[1]?.querySelector('.ln')?.textContent===f.start_line);if(!target){layout='document';renderFile();target=[...document.querySelectorAll('.docline')].find(row=>+row.querySelector('.ln')?.textContent===f.start_line)}document.querySelectorAll('.findingtarget').forEach(e=>e.classList.remove('findingtarget'));if(target){target.classList.add('findingtarget');target.scrollIntoView({block:'center',behavior:'smooth'})}toast(`定位 ${f.path.split('/').pop()}:${f.start_line}`)}
function adoptFinding(index){const f=agentJob?.report?.findings[index];if(!f||jobStale(f))return toast('文件已变化，请先重新审查');current=f.path;renderFile();renderList();const text=`[${f.severity} · ${f.kind==='verify'?'待核实':'问题'}] ${f.title}\n位置：${f.path}:${f.start_line}–${f.end_line}\n\n${f.body}\n\n依据：${f.evidence}\n\n建议：${f.suggestion}`;const existing=drafts.get(current)??file()?.note??'';$('#prompt').value=existing?existing+'\n\n'+text:text;drafts.set(current,$('#prompt').value);setAgentPanelMode('notes');$('#prompt').focus();toast('已填入反馈草稿；保存问题后可复制给修复 Agent')}
function setAgentPanelMode(mode){agentPanelMode=mode;$('#agentAssist').classList.toggle('hidden',mode!=='agent');$('#notesContent').classList.toggle('hidden',mode!=='notes');$('#panelAgent').classList.toggle('selected',mode==='agent');$('#panelNotes').classList.toggle('selected',mode==='notes');$('#agentpanel').classList.remove('hidden')}
async function updateAgent(){try{const response=await api('/api/agent-review');agentProviders=response.agents;agentJob=response.job;const currentProvider=$('#agentProvider').value;$('#agentProvider').innerHTML=agentProviders.map(p=>`<option value="${p.id}" ${p.available?'':'disabled'}>${p.name}${p.available?'':' · 未安装'}</option>`).join('');if(agentProviders.some(p=>p.id===currentProvider&&p.available))$('#agentProvider').value=currentProvider;renderAgentReview();renderList();if(agentJob?.status==='running'){if(!agentPolling)agentPolling=setInterval(updateAgent,2000)}else{clearInterval(agentPolling);agentPolling=null}}catch(e){$('#agentResult').innerHTML=`<div class="agenterror">无法连接审查服务：${esc(e.message)}</div>`}}
async function startAgent(scope){if(!data)return;try{const f=file();agentJob=await api('/api/agent-review',{provider:$('#agentProvider').value,scope,path:scope==='file'?f?.path:undefined,fingerprint:scope==='file'?f?.fingerprint:undefined});activeFinding=-1;renderList();setAgentPanelMode('agent');renderAgentReview();updateAgent()}catch(e){toast(e.message)}}
const panel=$('#agentpanel'),notes=document.createElement('div');notes.id='notesContent';notes.className='notescontent hidden';notes.append($('#chat'),$('.composer'));panel.append(notes);const tabs=document.createElement('div');tabs.className='paneltabs';tabs.innerHTML='<button class="selected" id="panelAgent">✧ Agent 审查</button><button id="panelNotes">审查反馈</button>';panel.querySelector('.agenthead').after(tabs);const assist=document.createElement('div');assist.id='agentAssist';assist.className='agentassist';assist.innerHTML='<div class="agentcontrols"><div class="agentcontrolrow"><label for="agentProvider">审查 Agent</label><select id="agentProvider" aria-label="审查 Agent"><option value="codex">Codex</option><option value="claude">Claude Code</option></select></div><div class="agentbuttons"><button class="outline" id="runFile">审查当前文件</button><button class="primary" id="runAll">审查全部变更</button><button class="hidden" id="cancelAgent">停止</button></div><p class="muted">使用本地 CLI 登录账号调用模型 · 仅分析快照</p></div><div id="agentResult" class="agentresult" aria-live="polite"></div>';panel.append(assist);$('.agenthead').innerHTML='<div class="avatar">✧</div><div>Agent 辅助 Review<div class="muted" style="font-size:10px;margin-top:3px">定位问题 · 人工确认</div></div><span class="spacer"></span><button id="closeAgent" aria-label="关闭审查面板">×</button>';$('#closeAgent').onclick=()=>panel.classList.add('hidden');$('#panelAgent').onclick=()=>setAgentPanelMode('agent');$('#panelNotes').onclick=()=>setAgentPanelMode('notes');$('#runFile').onclick=()=>startAgent('file');$('#runAll').onclick=()=>startAgent('all');$('#cancelAgent').onclick=async()=>{try{await api('/api/agent-review/cancel',{});await updateAgent()}catch(e){toast(e.message)}};$('#comment').onclick=()=>{setAgentPanelMode('notes');$('#prompt').focus()};$('#toggleAgent').textContent='侧栏开关';document.querySelectorAll('.sidebar .eyebrow')[2].textContent='改动来源未关联';const reviewAll=document.createElement('button');reviewAll.className='primary';reviewAll.id='reviewAllTop';reviewAll.textContent='✧ Agent 审查';$('#toggleAgent').before(reviewAll);reviewAll.onclick=()=>setAgentPanelMode('agent');$('#connect').textContent='✧ Agent 辅助审查';$('#connect').onclick=()=>setAgentPanelMode('agent');const originalRenderList=renderList;renderList=function(){originalRenderList();if(!agentJob?.report)return;document.querySelectorAll('[data-file]').forEach(b=>{const count=agentJob.report.findings.filter(f=>f.path===b.dataset.file&&!jobStale(f)).length;if(count){const badge=document.createElement('span');badge.className='aifilebadge';badge.textContent='✧ '+count;badge.title=`${count} 条 Agent 意见，需人工确认`;b.append(badge)}})};const originalRender=render;render=function(){originalRender();renderAgentReview()};const originalRenderFile=renderFile;renderFile=function(){originalRenderFile();if($('#runFile'))$('#runFile').disabled=agentJob?.status==='running'||!file()};updateAgent();
